import time
from functools import wraps

def onbellekle(ttl=None, saat=time.monotonic):
    def dekorator(f):
        cache = {}
        isabet = 0
        iska = 0

        @wraps(f)
        def sarmal(*args, **kwargs):
            nonlocal isabet, iska

            # 1. Hashlenemeyen argüman kontrolü (liste vb.)
            try:
                # İsimli argümanları sıralı bir tuple'a çevirerek anahtar oluşturma
                # Böylece {'n': 3} ile {'n': 3} aynı anahtarı verir.
                kwarg_key = tuple(sorted(kwargs.items()))
                anahtar = (args, kwarg_key)
                hash(anahtar)
            except TypeError:
                # Hashlenemeyen bir argüman varsa doğrudan çalıştır
                iska += 1
                return f(*args, **kwargs)

            # 2. Cache kontrolü
            if anahtar in cache:
                deger, zaman = cache[anahtar]
                if ttl is None or saat() - zaman > ttl:
                    # TTL geçmişse, bu kayıt geçersiz sayılmalı (yeniden hesaplanacak)
                    pass
                else:
                    isabet += 1
                    return deger

            # 3. Fonksiyonu çalıştırma
            iska += 1
            deger = f(*args, **kwargs)
            cache[anahtar] = (deger, saat())
            return deger

        def temizle():
            cache.clear()

        def bilgi():
            return {"isabet": isabet, "iska": iska}

        sarmal.temizle = temizle
        sarmal.bilgi = bilgi
        return sarmal
    return dekorator

# Test kodu (onbellek.py'deki hataları doğrulamak için)
def test():
    import time
    cagri = []

    @onbellekle()
    def kare(x):
        cagri.append(x)
        return x * x

    # Temel test
    assert kare(3) == 9 and kare(3) == 9 and cagri == [3], "Temel önbellek hatası"
    assert kare.bilgi() == {"isabet": 1, "iska": 1}, "Bilgi hatası (temel)"

    @onbellekle()
    def us(x, n=2):
        return x ** n

    # İsimli argümanlar testi (Hata veren kısım burasıydı)
    assert us(2, n=3) == 8 and us(2, n=4) == 16, "İsimli argümanlar hatası"

    # TTL testi
    @onbellekle(ttl=0.1)
    def gecici(x):
        return x

    assert gecici(1) == 1
    time.sleep(0.2)
    assert gecici(1) == 1 and gecici.bilgi()["iska"] == 2, "TTL hatası"

    # Docstring ve İsim koruma testi
    assert kare.__name__ == "kare", "İsim korunmadı"
    assert kare.__doc__ == "Karesini alır.", "Docstring korunmadı"

    # Hashlenemeyen argüman testi
    @onbellekle()
    def liste_al(l):
        return len(l)

    assert liste_al([1, 2]) == 2
    assert liste_al([1, 2]) == 2 and liste_al.bilgi()["iska"] == 1, "Hashlenemeyen argüman hatası"

    print("Tüm yerel testler başarıyla geçti!")

if __name__ == "__main__":
    test()

